 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-statements' AND catalog_hash='e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' AND payload_md5='240449ca1b613df5b215f5878410c9f7' AND md5((payload->'quizItems')::text)='b7f23066d7f3f666f8556cfaa8f7f0b7') THEN RAISE EXCEPTION 'Base archive or retained questions differ'; END IF;
