INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','reported-statements','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"reported-statements","title":"Reported speech: statements and reference","level":"B1","order":50,"summary":"Report someone’s message while adjusting tense, pronouns and time words to the reporting situation.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Reporting is a change of viewpoint","Backshift after a past reporting verb","Say and tell","Modals and continuing truth"],"rules":[{"title":"Reporting is a change of viewpoint","explanation":"Reported speech conveys a message without quoting the exact words. A that-clause commonly follows said or told. Pronouns and time expressions depend on who reports the message, where and when. Do not change them mechanically without checking the situation.","pattern":"“I’m ready.” → She said **she was ready**.","commonMistakes":["If the report is made on the same day, today may remain today. There is no compulsory word-replacement table independent of context."],"examples":["Backshift this report: She said, “I prepare the visitor guide every week.” → She said she **prepared** the visitor guide every week.","Backshift this report: She said, “I restore the old portrait every week.” → She said she **restored** the old portrait every week."],"skill":"form"},{"title":"Backshift after a past reporting verb","explanation":"When a report looks back from a later time, present often shifts to past, past to past perfect, and will to would. This is called backshift. It helps mark the original message as earlier than the reporting moment.","pattern":"“I work here.” → He said he **worked** there.","commonMistakes":["Backshift is not always necessary if the message is still true or relevant. The exercises explicitly request it where needed."],"examples":["Report the plan with backshift: “I will prepare the visitor guide.” → She said she **would prepare** the visitor guide.","Report the plan with backshift: “I will restore the old portrait.” → She said she **would restore** the old portrait."],"skill":"meaning"},{"title":"Say and tell","explanation":"Use **say something** or **say to someone**. Use **tell someone something** with an object naming the listener. These are different verb patterns. Told me that and said to me that can both be correct.","pattern":"She **told me** the news. / She **said** she was tired.","commonMistakes":["She said me is not the standard pattern; use told me or said to me."],"examples":["Choose the verb pattern: “She **told** me that she would prepare the visitor guide.”","Choose the verb pattern: “She **told** me that she would restore the old portrait.”"],"skill":"contrast"},{"title":"Modals and continuing truth","explanation":"Will commonly becomes would and can becomes could in a backshifted report. Would, could, should and might often remain unchanged. A current fact can remain in present tense when the reporter endorses it as still true.","pattern":"He said the Earth **is** round.","commonMistakes":["Reported speech is about accurate meaning, not changing every verb merely because said is past."],"examples":["Backshift a finished past statement: “We prepared the visitor guide.” → They said they **had prepared** the visitor guide.","Backshift a finished past statement: “We restored the old portrait.” → They said they **had restored** the old portrait."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Report someone’s message while adjusting tense, pronouns and time words to the reporting situation.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Reporting is a change of viewpoint","explanation":"Reported speech conveys a message without quoting the exact words. A that-clause commonly follows said or told. Pronouns and time expressions depend on who reports the message, where and when. Do not change them mechanically without checking the situation.","pattern":"“I’m ready.” → She said **she was ready**.","commonMistakes":["If the report is made on the same day, today may remain today. There is no compulsory word-replacement table independent of context."],"examples":["Backshift this report: She said, “I prepare the visitor guide every week.” → She said she **prepared** the visitor guide every week.","Backshift this report: She said, “I restore the old portrait every week.” → She said she **restored** the old portrait every week."],"skill":"form","id":"reported-statements-foundation-1","domain":"content-clauses","referenceIds":["bc-reported-statements"],"readingVersion":"core-2026-09-v3"},{"title":"Backshift after a past reporting verb","explanation":"When a report looks back from a later time, present often shifts to past, past to past perfect, and will to would. This is called backshift. It helps mark the original message as earlier than the reporting moment.","pattern":"“I work here.” → He said he **worked** there.","commonMistakes":["Backshift is not always necessary if the message is still true or relevant. The exercises explicitly request it where needed."],"examples":["Report the plan with backshift: “I will prepare the visitor guide.” → She said she **would prepare** the visitor guide.","Report the plan with backshift: “I will restore the old portrait.” → She said she **would restore** the old portrait."],"skill":"meaning","id":"reported-statements-foundation-2","domain":"content-clauses","referenceIds":["bc-reported-statements"],"readingVersion":"core-2026-09-v3"},{"title":"Say and tell","explanation":"Use **say something** or **say to someone**. Use **tell someone something** with an object naming the listener. These are different verb patterns. Told me that and said to me that can both be correct.","pattern":"She **told me** the news. / She **said** she was tired.","commonMistakes":["She said me is not the standard pattern; use told me or said to me."],"examples":["Choose the verb pattern: “She **told** me that she would prepare the visitor guide.”","Choose the verb pattern: “She **told** me that she would restore the old portrait.”"],"skill":"contrast","id":"reported-statements-foundation-3","domain":"content-clauses","referenceIds":["bc-reported-statements"],"readingVersion":"core-2026-09-v3"},{"title":"Modals and continuing truth","explanation":"Will commonly becomes would and can becomes could in a backshifted report. Would, could, should and might often remain unchanged. A current fact can remain in present tense when the reporter endorses it as still true.","pattern":"He said the Earth **is** round.","commonMistakes":["Reported speech is about accurate meaning, not changing every verb merely because said is past."],"examples":["Backshift a finished past statement: “We prepared the visitor guide.” → They said they **had prepared** the visitor guide.","Backshift a finished past statement: “We restored the old portrait.” → They said they **had restored** the old portrait."],"skill":"application","id":"reported-statements-foundation-4","domain":"content-clauses","referenceIds":["bc-reported-statements"],"readingVersion":"core-2026-09-v3"},{"domain":"negation","id":"negative-raising","title":"I don’t think and the location of the negative","explanation":"With verbs such as think, believe and suppose, English often places the negative in the main clause while conveying a negative judgement about the embedded proposition. I don’t think she is ready usually suggests that the speaker thinks she is not ready, but context can instead deny having a settled belief.","pattern":"I **don’t think** it will work.","examples":["I **don’t suppose** they will agree.","I **think it won’t work** makes the negative prediction more explicit."],"commonMistakes":["This pattern does not apply freely to every reporting verb. I didn’t say he left denies the act of saying it and does not automatically mean I said he didn’t leave."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"content-clauses","id":"reporting-reference-backshift","title":"Backshift, pronouns and reporting perspective","explanation":"Reporting changes the viewpoint from the original speaker to the reporter. Past reporting verbs often invite backshift, but a statement still treated as true can keep its original tense. Pronouns and time expressions change only if the referents or reference time change. Direct quotation preserves the original wording; indirect reporting conveys the message.","pattern":"“I am ready.” → She said **she was ready**.","examples":["She said **she lives nearby**, and she still does.","On Tuesday he said, “I’ll leave tomorrow.” Later: he said he would leave **on Wednesday**."],"commonMistakes":["Backshift is not an instruction to replace every present with past regardless of meaning. The reporter’s commitment and time frame matter."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["“I’m ready.” → She said **she was ready**.","“I work here.” → He said he **worked** there.","She **told me** the news. / She **said** she was tired.","He said the Earth **is** round."],"readingVersion":"core-2026-09-v4"},"stage":"5 · Complex sentences","prerequisites":["relative-clauses"],"readingReferenceIds":["bc-reported-statements","cambridge-negation","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-statements'
